package com.rekluzlabs.makokolorize.ui.componentsimport android.graphics.BitmapFactoryimport android.net.Uriimport androidx.compose.foundation.Canvasimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.gestures.detectHorizontalDragGesturesimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.aspectRatioimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.offsetimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableFloatStateOfimport androidx.compose.runtime.produceStateimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipToBoundsimport androidx.compose.ui.draw.drawWithContentimport androidx.compose.ui.geometry.Offsetimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.drawscope.clipRectimport androidx.compose.ui.input.pointer.pointerInputimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport coil.compose.AsyncImageimport coil.request.ImageRequest@Composablefun ImageComparison(    beforeUri: Uri?,    afterUri: Uri?,    modifier: Modifier = Modifier) {    val context = LocalContext.current    var dividerPosition by remember { mutableFloatStateOf(0.5f) }    val imageUri = beforeUri ?: afterUri    val aspectRatio by produceState(1f) {        val uri = imageUri ?: return@produceState        try {            context.contentResolver.openInputStream(uri)?.use { input ->                val opts = BitmapFactory.Options().apply { inJustDecodeBounds = true }                BitmapFactory.decodeStream(input, null, opts)                if (opts.outWidth > 0 && opts.outHeight > 0) {                    value = opts.outWidth.toFloat() / opts.outHeight.toFloat()                }            }        } catch (_: Exception) {}    }    Box(        modifier = modifier            .fillMaxSize()            .clipToBounds(),        contentAlignment = Alignment.Center    ) {        Box(            modifier = Modifier                .fillMaxSize()                .aspectRatio(aspectRatio)        ) {            afterUri?.let {                AsyncImage(                    model = ImageRequest.Builder(LocalContext.current)                        .data(it)                        .crossfade(true)                        .build(),                    contentDescription = "After",                    modifier = Modifier.fillMaxSize(),                    contentScale = ContentScale.Fit                )            }            beforeUri?.let {                Box(                    modifier = Modifier                        .fillMaxSize()                        .drawWithContent {                            val splitX = size.width * dividerPosition                            clipRect(right = splitX) {                                this@drawWithContent.drawContent()                            }                        }                ) {                    AsyncImage(                        model = ImageRequest.Builder(LocalContext.current)                            .data(it)                            .crossfade(true)                            .build(),                        contentDescription = "Before",                        modifier = Modifier.fillMaxSize(),                        contentScale = ContentScale.Fit                    )                    PillLabel(                        text = "Before",                        modifier = Modifier                            .align(Alignment.TopStart)                            .offset(x = 12.dp, y = 12.dp)                    )                }            }            if (afterUri != null) {                PillLabel(                    text = "After",                    modifier = Modifier                        .align(Alignment.TopEnd)                        .offset(x = (-12).dp, y = 12.dp)                )            }            Box(                modifier = Modifier                    .fillMaxSize()                    .pointerInput(Unit) {                        detectHorizontalDragGestures { change, dragAmount ->                            change.consume()                            val width = size.width.toFloat()                            dividerPosition = ((dividerPosition * width + dragAmount) / width)                                .coerceIn(0f, 1f)                        }                    }            )            Canvas(modifier = Modifier.fillMaxSize()) {                val splitX = size.width * dividerPosition                val h = size.height                drawLine(                    color = Color.White,                    start = Offset(splitX, 0f),                    end = Offset(splitX, h),                    strokeWidth = 3f                )                val handleRadius = 16f                drawCircle(                    color = Color.White,                    radius = handleRadius,                    center = Offset(splitX, h / 2f)                )                drawCircle(                    color = Color(0xFF666666),                    radius = handleRadius - 3f,                    center = Offset(splitX, h / 2f)                )            }        }    }}@Composableprivate fun PillLabel(    text: String,    modifier: Modifier = Modifier) {    Box(        modifier = modifier            .background(                color = Color.Black.copy(alpha = 0.55f),                shape = RoundedCornerShape(50)            )            .padding(horizontal = 12.dp, vertical = 4.dp)    ) {        Text(            text = text,            fontSize = 12.sp,            fontWeight = FontWeight.SemiBold,            color = Color.White        )    }}